const { test, expect } = require('@playwright/test');

test('loads data on button click', async ({ page }) => {
  // Navigate to the page.
  await page.goto('http://localhost:8080/flaky.html');

  // Click the button that triggers the async load.
  await page.click('#loadBtn');

  // Wait for network activity to settle – this helps when the button triggers a fetch.
  await page.waitForLoadState('networkidle');

  // Locate the result element and wait until it contains the expected text.
  const result = page.locator('#result');
  await expect(result).toHaveText('Data Loaded', { timeout: 15000 });
});

const { test, expect } = require('@playwright/test');

test('loads data on button click', async ({ page }) => {
  await page.goto('http://localhost:8080/flaky.html');
  await page.click('#loadBtn');

  // Poll the DOM until the result element contains the exact text.
  await page.waitForFunction(() => {
    const el = document.querySelector('#result');
    return el && el.textContent.trim() === 'Data Loaded';
  }, null, { timeout: 15000 });

  // Final assertion – the text should now be present.
  const text = await page.textContent('#result');
  expect(text).toBe('Data Loaded');
});

